import 'package:flutter/material.dart'; import 'package:flutter_riverpod/flutter_riverpod.dart'; import '../../../app/providers.dart'; import '../../../core/utils/validators.dart';
class ForgotPasswordScreen extends ConsumerStatefulWidget {const ForgotPasswordScreen({super.key});@override ConsumerState<ForgotPasswordScreen> createState()=>_ForgotPasswordScreenState();}class _ForgotPasswordScreenState extends ConsumerState<ForgotPasswordScreen>{final _form=GlobalKey<FormState>();final _email=TextEditingController();bool _loading=false;@override void dispose(){_email.dispose();super.dispose();}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('استعادة كلمة المرور')),body:Padding(padding:const EdgeInsets.all(24),child:Form(key:_form,child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('أدخل بريدك الإلكتروني وسنرسل لك رابط إعادة التعيين.'),const SizedBox(height:20),TextFormField(controller:_email,validator:Validators.email,decoration:const InputDecoration(labelText:'البريد الإلكتروني')),const SizedBox(height:16),FilledButton(onPressed:_loading?null:()async{if(!(_form.currentState?.validate()??false))return;setState(()=>_loading=true);try{await ref.read(authRepositoryProvider).resetPassword(_email.text.trim());if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تم إرسال رابط إعادة التعيين.')));}finally{if(mounted)setState(()=>_loading=false);}},child:Text(_loading?'جارٍ الإرسال…':'إرسال الرابط'))])));}
